+// API keys and roles. A key belongs to one role; roles are ordered, each may
+// do what the ones before it may: viewer (read), cook (kitchen work), manager
+// (everything).
+import { createHash, timingSafeEqual } from "node:crypto";
+
+/** Roles from least to most allowed. */
+export const ROLES = Object.freeze(["viewer", "cook", "manager"]);
+
+const digest = (s) => createHash("sha256").update(String(s)).digest();
+
+/** The API key record for `key`, or null. Compares every key in constant time. */
+export function findKey(store, key) {
+  if (typeof key !== "string" || key === "") return null;
+  const wanted = digest(key);
+  let found = null;
+  for (const k of store.data.apiKeys ?? []) {
+    if (typeof k.key !== "string" || k.key === "") continue;
+    if (timingSafeEqual(digest(k.key), wanted) && !found) found = k;
+  }
+  return found;
+}
+
+/** Whether `role` may do what `needed` (a role) may do. Unknown roles may do nothing. */
+export function allows(role, needed) {
+  const have = ROLES.indexOf(role);
+  const want = ROLES.indexOf(needed);
+  return have >= 0 && want >= 0 && have >= want;
+}
