+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, bearer, KEYS } from "./helpers.js";
+
+test("a request without a key or with an unknown key is 401", async () => {
+  const { raw, store } = app();
+  for (const headers of [{}, { authorization: "Bearer nope" }, { authorization: KEYS.manager }, { authorization: "Bearer " }]) {
+    const res = await raw({ path: "/items", headers });
+    assert.equal(res.status, 401);
+    assert.equal(res.body.error.code, "unauthorized");
+    assert.equal(res.headers["www-authenticate"], "Bearer");
+  }
+  const post = await raw({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  assert.equal(post.status, 401);
+  assert.equal(store.data.audit.length, 0);
+  assert.equal((await raw({ path: "/nope" })).status, 401);
+});
+
+test("the scheme and header name are case-insensitive", async () => {
+  const { raw } = app();
+  assert.equal((await raw({ path: "/items", headers: { Authorization: `bearer ${KEYS.viewer}` } })).status, 200);
+});
+
+test("viewers may only read", async () => {
+  const { handle, store } = app(undefined, { role: "viewer" });
+  assert.equal((await handle({ path: "/items" })).status, 200);
+  const before = JSON.stringify(store.data.batches);
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  assert.equal(res.status, 403);
+  assert.equal(res.body.error.code, "forbidden");
+  assert.equal(JSON.stringify(store.data.batches), before);
+  assert.equal((await handle({ path: "/audit" })).status, 403);
+});
+
+test("cooks may cook, waste, log temperatures and enter counts, nothing else", async () => {
+  const { handle, raw } = app(undefined, { role: "cook" });
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", body: { qty: 1, reason: "spill" } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", body: { location: "fridge", celsius: 3 } })).status, 201);
